import {
  AssessmentInputs,
  CalculatedOpportunity,
  DomainScore,
  EngineResult,
} from './types';
import { getBenchmark } from './benchmarks';

export const ENGINE_VERSION = '1.0.0';

export const METHODOLOGY_DISCLAIMER =
  'Diagnostic Disclaimer: All scores, calculations, and financial opportunity estimates generated by the Adyant Nexa Growth Engine are indicative figures derived from submitted business inputs and standardized fashion retail benchmarks. They do not constitute guaranteed earnings, guaranteed savings, or financial warranties.';

/**
 * Rounds numbers to diagnostic-friendly numbers (nearest 5,000 or 10,000)
 */
function roundOpportunity(val: number): number {
  if (val <= 0) return 0;
  if (val < 50000) return Math.round(val / 1000) * 1000;
  if (val < 500000) return Math.round(val / 5000) * 5000;
  return Math.round(val / 10000) * 10000;
}

/**
 * 1. Inventory & Dead Stock Opportunity
 */
export function calculateInventoryOpportunity(
  inputs: AssessmentInputs
): CalculatedOpportunity {
  const benchmark = getBenchmark(inputs.industry || 'fashion_retail');
  const inventoryValue = inputs.inventoryValue || 0;
  const deadStockPct = inputs.slowDeadStockPercentage ?? 0;

  if (!inputs.inventoryValue && !inputs.slowDeadStockPercentage) {
    return {
      category: 'inventory',
      title: 'Dead Stock & Capital Lock Diagnostic',
      issueSummary: 'Insufficient inventory metrics provided.',
      estimatedAnnualOpportunity: 0,
      priority: 'LOW',
      recommendedAction: 'Provide inventory valuation and dead stock % to calculate capital recovery.',
      isSufficientData: false,
    };
  }

  const excessPct = Math.max(0, deadStockPct - benchmark.healthyDeadStockPct);
  const excessDeadStock = (inventoryValue * excessPct) / 100;
  const carryingCostLeakage = excessDeadStock * benchmark.inventoryCarryingCostRate;
  const totalOpportunity = roundOpportunity(excessDeadStock + carryingCostLeakage);

  let priority: 'HIGH' | 'MEDIUM' | 'LOW' = 'LOW';
  if (deadStockPct > 25 || totalOpportunity > 500000) priority = 'HIGH';
  else if (deadStockPct > 15 || totalOpportunity > 150000) priority = 'MEDIUM';

  return {
    category: 'inventory',
    title: 'Inventory Capital & Dead Stock Recovery',
    issueSummary: `Estimated ${deadStockPct}% of inventory is slow/dead stock (benchmark is <${benchmark.healthyDeadStockPct}%). High working capital is locked in non-moving merchandise.`,
    estimatedAnnualOpportunity: totalOpportunity,
    priority,
    recommendedAction: 'Implement markdown velocity rules, vendor return terms, and automated reorder caps on slow-moving SKUs.',
    isSufficientData: true,
  };
}

/**
 * 2. Margin & Discount Erosion Opportunity
 */
export function calculateMarginOpportunity(
  inputs: AssessmentInputs
): CalculatedOpportunity {
  const benchmark = getBenchmark(inputs.industry || 'fashion_retail');
  const monthlyRevenue = inputs.monthlyRevenue || 0;
  const annualRevenue = monthlyRevenue * 12;
  const discountPct = inputs.avgDiscountPercentage ?? 0;

  if (!inputs.monthlyRevenue || inputs.avgDiscountPercentage === undefined) {
    return {
      category: 'margins',
      title: 'Margin & Discount Erosion Diagnostic',
      issueSummary: 'Insufficient revenue or discount metrics provided.',
      estimatedAnnualOpportunity: 0,
      priority: 'LOW',
      recommendedAction: 'Provide monthly revenue and average discount % to evaluate profit leakage.',
      isSufficientData: false,
    };
  }

  const excessDiscountPct = Math.max(0, discountPct - benchmark.healthyDiscountPct);
  const rawLeakage = annualRevenue * (excessDiscountPct / 100) * 0.70;
  const totalOpportunity = roundOpportunity(rawLeakage);

  let priority: 'HIGH' | 'MEDIUM' | 'LOW' = 'LOW';
  if (discountPct > 25 || totalOpportunity > 400000) priority = 'HIGH';
  else if (discountPct > 18 || totalOpportunity > 100000) priority = 'MEDIUM';

  return {
    category: 'margins',
    title: 'Margin Preservation & Discount Optimization',
    issueSummary: `Average discount rate of ${discountPct}% exceeds healthy retail benchmark (${benchmark.healthyDiscountPct}%). Unplanned discounting directly erodes net profitability.`,
    estimatedAnnualOpportunity: totalOpportunity,
    priority,
    recommendedAction: 'Shift from broad storewide sales to targeted bundle offers, tier-based loyalty discounts, and full-margin product stories.',
    isSufficientData: true,
  };
}

/**
 * 3. Customer Retention & Repeat Purchase Opportunity
 */
export function calculateRetentionOpportunity(
  inputs: AssessmentInputs
): CalculatedOpportunity {
  const benchmark = getBenchmark(inputs.industry || 'fashion_retail');
  const monthlyRevenue = inputs.monthlyRevenue || 0;
  const annualRevenue = monthlyRevenue * 12;
  const repeatPct = inputs.repeatPurchasePercentage ?? 0;
  const marginPct = inputs.grossMarginPercentage || benchmark.healthyGrossMarginPct;

  if (!inputs.monthlyRevenue || inputs.repeatPurchasePercentage === undefined) {
    return {
      category: 'retention',
      title: 'Customer Repeat Purchase Diagnostic',
      issueSummary: 'Insufficient repeat customer metrics provided.',
      estimatedAnnualOpportunity: 0,
      priority: 'LOW',
      recommendedAction: 'Provide repeat purchase percentage to calculate customer lifetime value leakage.',
      isSufficientData: false,
    };
  }

  const repeatGapPct = Math.max(0, benchmark.targetRepeatRatePct - repeatPct);
  const rawOpportunity = annualRevenue * (repeatGapPct / 100) * (marginPct / 100);
  const totalOpportunity = roundOpportunity(rawOpportunity);

  let priority: 'HIGH' | 'MEDIUM' | 'LOW' = 'LOW';
  if (repeatPct < 20 || totalOpportunity > 500000) priority = 'HIGH';
  else if (repeatPct < 30 || totalOpportunity > 150000) priority = 'MEDIUM';

  return {
    category: 'retention',
    title: 'Customer Retention & LTV Recovery',
    issueSummary: `Repeat purchase rate of ${repeatPct}% is below the target fashion retail benchmark (${benchmark.targetRepeatRatePct}%). One-time buyers represent high uncaptured customer lifetime value.`,
    estimatedAnnualOpportunity: totalOpportunity,
    priority,
    recommendedAction: 'Deploy automated WhatsApp post-purchase follow-up sequences, VIP buyer rewards, and automated 60-day winback campaigns.',
    isSufficientData: true,
  };
}

/**
 * 4. Marketing Acquisition Efficiency Opportunity
 */
export function calculateMarketingOpportunity(
  inputs: AssessmentInputs
): CalculatedOpportunity {
  const monthlySpend = inputs.monthlyMarketingSpend || 0;
  const annualSpend = monthlySpend * 12;
  const conversionRate = inputs.conversionRate ?? 1.2;

  if (!inputs.monthlyMarketingSpend) {
    return {
      category: 'marketing',
      title: 'Marketing Acquisition Efficiency Diagnostic',
      issueSummary: 'No marketing spend details provided.',
      estimatedAnnualOpportunity: 0,
      priority: 'LOW',
      recommendedAction: 'Provide monthly marketing spend to calculate ad efficiency opportunities.',
      isSufficientData: false,
    };
  }

  let inefficiencyFactor = 0.10;
  if (conversionRate < 1.5) inefficiencyFactor = 0.35;
  else if (conversionRate <= 3.0) inefficiencyFactor = 0.20;

  const rawOpportunity = annualSpend * inefficiencyFactor;
  const totalOpportunity = roundOpportunity(rawOpportunity);

  let priority: 'HIGH' | 'MEDIUM' | 'LOW' = 'LOW';
  if (inefficiencyFactor >= 0.35 || totalOpportunity > 300000) priority = 'HIGH';
  else if (totalOpportunity > 80000) priority = 'MEDIUM';

  return {
    category: 'marketing',
    title: 'Marketing ROI & Lead Conversion Optimization',
    issueSummary: `Estimated conversion rate of ${conversionRate}% indicates paid traffic leakage. Up to ${Math.round(inefficiencyFactor * 100)}% of marketing budget is spent on unoptimized funnels.`,
    estimatedAnnualOpportunity: totalOpportunity,
    priority,
    recommendedAction: 'Audit ad targeting creatives, implement landing page lead capture popups, and optimize local Google/Meta store-visit campaigns.',
    isSufficientData: true,
  };
}

/**
 * Synthesizes individual category sub-scores
 */
export function calculateDomainScores(inputs: AssessmentInputs) {
  const benchmark = getBenchmark(inputs.industry || 'fashion_retail');

  // Inventory Score
  const deadStockPct = inputs.slowDeadStockPercentage ?? 15;
  const inventoryScore = Math.max(
    10,
    Math.min(100, Math.round(100 - Math.max(0, deadStockPct - benchmark.healthyDeadStockPct) * 3.5))
  );

  // Margin Score
  const discountPct = inputs.avgDiscountPercentage ?? 18;
  const marginScore = Math.max(
    10,
    Math.min(100, Math.round(100 - Math.max(0, discountPct - benchmark.healthyDiscountPct) * 4))
  );

  // Retention Score
  const repeatPct = inputs.repeatPurchasePercentage ?? 25;
  const retentionScore = Math.max(
    10,
    Math.min(100, Math.round((repeatPct / benchmark.targetRepeatRatePct) * 100))
  );

  // Marketing Score
  const convRate = inputs.conversionRate ?? 1.5;
  const marketingScore = Math.max(
    10,
    Math.min(100, Math.round(Math.min(100, (convRate / 3.0) * 100)))
  );

  const getScoreStatus = (score: number): DomainScore['status'] => {
    if (score >= 80) return 'EXCELLENT';
    if (score >= 65) return 'HEALTHY';
    if (score >= 45) return 'MODERATE_LEAKAGE';
    return 'SEVERE_LEAKAGE';
  };

  return {
    inventory: {
      score: inventoryScore,
      label: 'Inventory & Dead Stock',
      status: getScoreStatus(inventoryScore),
      summary: `${deadStockPct}% dead stock detected`,
    },
    margins: {
      score: marginScore,
      label: 'Margin & Pricing',
      status: getScoreStatus(marginScore),
      summary: `${discountPct}% average discount rate`,
    },
    retention: {
      score: retentionScore,
      label: 'Customer Retention',
      status: getScoreStatus(retentionScore),
      summary: `${repeatPct}% repeat buyer rate`,
    },
    marketing: {
      score: marketingScore,
      label: 'Marketing Efficiency',
      status: getScoreStatus(marketingScore),
      summary: `${convRate}% estimated conversion rate`,
    },
  };
}

/**
 * Synthesizes overall Growth Score (0 to 100)
 */
export function calculateGrowthScore(inputs: AssessmentInputs): number {
  const domainScores = calculateDomainScores(inputs);
  const weightedScore =
    domainScores.inventory.score * 0.35 +
    domainScores.margins.score * 0.25 +
    domainScores.retention.score * 0.20 +
    domainScores.marketing.score * 0.20;

  return Math.max(10, Math.min(100, Math.round(weightedScore)));
}

/**
 * Main Engine Entry Point: Synthesizes complete assessment output
 */
export function synthesizeAssessmentResult(inputs: AssessmentInputs): EngineResult {
  const growthScore = calculateGrowthScore(inputs);
  const domainScores = calculateDomainScores(inputs);

  const invOpp = calculateInventoryOpportunity(inputs);
  const marginOpp = calculateMarginOpportunity(inputs);
  const retOpp = calculateRetentionOpportunity(inputs);
  const mktOpp = calculateMarketingOpportunity(inputs);

  const allOpportunities = [invOpp, marginOpp, retOpp, mktOpp].filter(
    (opp) => opp.isSufficientData && opp.estimatedAnnualOpportunity > 0
  );

  // Sort opportunities by estimated annual rupee value descending
  allOpportunities.sort(
    (a, b) => b.estimatedAnnualOpportunity - a.estimatedAnnualOpportunity
  );

  const totalEstimatedAnnualOpportunity = allOpportunities.reduce(
    (sum, opp) => sum + opp.estimatedAnnualOpportunity,
    0
  );

  let overallScoreStatus: EngineResult['overallScoreStatus'] = 'MODERATE_EFFICIENCY';
  if (growthScore >= 80) overallScoreStatus = 'HIGH_EFFICIENCY';
  else if (growthScore >= 60) overallScoreStatus = 'MODERATE_EFFICIENCY';
  else if (growthScore >= 40) overallScoreStatus = 'SIGNIFICANT_LEAKAGE';
  else overallScoreStatus = 'CRITICAL_LEAKAGE';

  return {
    engineVersion: ENGINE_VERSION,
    growthScore,
    overallScoreStatus,
    totalEstimatedAnnualOpportunity,
    domainScores,
    topOpportunities: allOpportunities.slice(0, 3),
    allOpportunities,
    calculatedAt: new Date().toISOString(),
    disclaimer: METHODOLOGY_DISCLAIMER,
  };
}
